让我创建一个基于字符的贪吃蛇游戏。","role":"assistant","tool_calls":[{"function":{"arguments":"{"file_path":"/Users/shuochen/Project/Agent/workspace/snake_cli.py","content":"#!/usr/bin/env python3\n\"\"\"\n命令行版贪吃蛇游戏\n使用方向键控制蛇的移动\n\"\"\"\n\nimport sys\nimport time\nimport random\nimport select\nimport termios\nimport tty\n\nclass SnakeCLI:\n    def __init__(self):\n        # 游戏参数\n        self.width = 30\n        self.height = 15\n        self.speed = 0.15  # 游戏速度（秒）\n        \n        # 初始化蛇\n        start_x = self.width // 2\n        start_y = self.height // 2\n        self.snake = [(start_x, start_y)]\n        self.direction = (1, 0)  # 初始向右\n        self.next_direction = (1, 0)\n        \n        # 食物\n        self.food = self.generate_food()\n        \n        # 游戏状态\n        self.score = 0\n        self.game_over = False\n        \n        # 保存终端设置\n        self.old_settings = termios.tcgetattr(sys.stdin)\n    \n    def generate_food(self):\n        \"\"\"生成食物位置\"\"\"\n        while True:\n            food = (random.randint(1, self.width - 2),\n                    random.randint(1, self.height - 2))\n            if food not in self.snake:\n                return food\n    \n    def get_key(self):\n        \"\"\"获取键盘输入（非阻塞）\"\"\"\n        if select.select([sys.stdin], [], [], 0)[0]:\n            ch = sys.stdin.read(1)\n            return ch\n        return None\n    \n    def handle_input(self):\n        \"\"\"处理输入\"\"\"\n        key = self.get_key()\n        if key:\n            # 方向键的转义序列\n            if key == '\\x1b':\n                key = self.get_key()\n                if key == '[':\n                    key = self.get_key()\n                    if key == 'A' and self.direction != (0, 1):  # 上\n                        self.next_direction = (0, -1)\n                    elif key == 'B' and self.direction != (0, -1):  # 下\n                        self.next_direction = (0, 1)\n                    elif key == 'C' and self.direction != (-1, 0):  # 右\n                        self.next_direction = (1, 0)\n                    elif key == 'D' and self.direction != (1, 0):  # 左\n                        self.next_direction = (-1, 0)\n    \n    def update(self):\n        \"\"\"更新游戏状态\"\"\"\n        self.direction = self.next_direction\n        \n        # 计算新头部位置\n        head_x, head_y = self.snake[0]\n        new_x = head_x + self.direction[0]\n        new_y = head_y + self.direction[1]\n        \n        # 边界检测\n        if new_x <= 0 or new_x >= self.width - 1 or new_y <= 0 or new_y >= self.height - 1:\n            self.game_over = True\n            return\n        \n        # 检测碰撞\n        if (new_x, new_y) in self.snake:\n            self.game_over = True\n            return\n        \n        # 移动蛇\n        new_head = (new_x, new_y)\n        self.snake.insert(0, new_head)\n        \n        # 检测食物\n        if new_head == self.food:\n            self.score += 1\n            self.food = self.generate_food()\n        else:\n            self.snake.pop()\n    \n    def draw(self):\n        \"\"\"绘制游戏画面\"\"\"\n        # 清屏\n        print(\"\\033[H\\033[J\", end=\"\")\n        \n        # 绘制顶部信息\n        print(f\"  命令行贪吃蛇 - 分数: {self.score}\")\n        print(\"  使用方向键控制，按 Ctrl+C 退出\")\n        print(\"  \" + \"=\" * (self.width - 2))\n        \n        # 绘制游戏区域\n        for y in range(self.height):\n            row = \"  \"\n            for x in range(self.width):\n                if y == 0 or y == self.height - 1 or x == 0 or x == self.width - 1:\n                    row += \"#\"  # 边界\n                elif (x, y) == self.food:\n                    row += \"●\"  # 食物\n                elif (x, y) == self.snake[0]:\n                    row += \"@\"  # 蛇头\n                elif (x, y) in self.snake:\n                    row += \"o\"  # 蛇身\n                else:\n                    row += \" \"  # 空地\n            print(row)\n        \n        print(\"  \" + \"=\" * (self.width - 2))\n    \n    def run(self):\n        \"\"\"运行游戏\"\"\"\n        print(\"\\033[2J\\033[H\", end=\"\")  # 清屏\n        \n        # 设置终端为原始模式\n        try:\n            tty.setraw(sys.stdin.fileno())\n            \n            while not self.game_over:\n                self.handle_input()\n                self.update()\n                self.draw()\n                time.sleep(self.speed)\n        \n        except KeyboardInterrupt:\n            print(\"\\n\\n游戏已退出！\")\n        \n        finally:\n            # 恢复终端设置\n            termios.tcsetattr(sys.stdin, termios.TCSADRAIN, self.old_settings)\n            \n            # 显示游戏结束信息\n            print(\"\\033[H\\033[J\", end=\"\")\n            print(\"=\" * 50)\n            print(\"  游戏结束!\")\n            print(f\"  最终分数: {self.score}\")\n            print(\"=\" * 50)\n\ndef main():\n    print(\"\\033[2J\\033[H\", end=\"\")\n    print(\"=\" * 50)\n    print(\"  命令行贪吃蛇小游戏\")\n    print(\"=\" * 50)\n    print(\"\\n操作说明:\")\n    print(\"  ↑ 向上移动\")\n    print(\"  ↓ 向下移动\")\n    print(\"  ← 向左移动\")\n    print(\"  → 向右移动\")\n    print(\"  Ctrl+C 退出游戏\")\n    print(\"\\n游戏即将启动，准备好了吗？\")\n    print(\"按任意键开始...\")\n    \n    input()\n    \n    game = SnakeCLI()\n    game.run()\n\nif __name__ == \"__main__\":\n    main()\n"}","name":"write_file"},"id":"call_-7667138775142625670","index":0,"type":"function"}]}}
